<?php
namespace App\Http\Controllers;
use App\Models\Venue;use App\Models\Booking;use App\Services\BookingEngine;use Carbon\CarbonImmutable;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class BookingController extends Controller {
 private function input(Request $r){return $r->validate(['date'=>'required|date_format:Y-m-d','start'=>'required|numeric|between:0,47.984','hours'=>'required|integer|between:1,24','guests'=>'required|integer|min:1','extras'=>'sometimes|array|max:100','extras.*'=>'array:id,quantity','extras.*.id'=>'required|string|max:64|distinct','extras.*.quantity'=>'required|integer|between:1,100000']);}
 public function availability(Request $r,Venue $venue,BookingEngine $engine){abort_unless($venue->published,404);$d=$r->validate(['month'=>'required|date_format:Y-m']);$first=CarbonImmutable::createFromFormat('!Y-m',$d['month'],$venue->settings['timezone']);abort_if($first->gt(now()->addYears(2)),422);$occupied=$venue->bookings()->blocking()->where('blocked_from','<',$first->addMonth()->addDays(2)->utc())->where('blocked_until','>',$first->subDays(2)->utc())->get(['blocked_from','blocked_until']);$days=[];for($i=0;$i<$first->daysInMonth;$i++){$date=$first->addDays($i)->format('Y-m-d');$slots=[];$s=$venue->settings;$hours=$s['mode']==='day'?$s['included_hours']:1;for($minute=$s['open_hour']*60+($s['open_minute']??0)+$s['prep_minutes'];$minute<$s['close_hour']*60+($s['close_minute']??0);$minute+=30){$h=$minute/60;try{$q=$engine->quote($venue,['date'=>$date,'start'=>$h,'hours'=>$hours,'guests'=>1]);if(!$occupied->contains(fn($b)=>$b->blocked_from->lt(CarbonImmutable::parse($q['blocked_until']))&&$b->blocked_until->gt(CarbonImmutable::parse($q['blocked_from']))))$slots[]=$h;}catch(\Illuminate\Validation\ValidationException $e){}}$days[]=['date'=>$date,'available'=>count($slots)>0,'slots'=>$slots];}return ['days'=>$days];}
 public function quote(Request $r,Venue $venue,BookingEngine $engine){abort_unless($venue->published,404);$q=$engine->quote($venue,$this->input($r));return ['quote'=>$q,'available'=>!$engine->hasConflict($venue,$q)];}
 public function store(Request $r,Venue $venue,BookingEngine $engine){$guard=$r->validate(['policy_accepted'=>'required|accepted','expected_total'=>'sometimes|required|integer|min:0','expected_version'=>'sometimes|required|string|max:50']);return response()->json($engine->reserve($venue,$r->user()->id,array_merge($this->input($r),$guard)),201);}
 public function mine(Request $r){return Booking::where('user_id',$r->user()->id)->with(['venue:id,name,slug','payments','checkoutAttempts'])->withSum('payments','amount')->orderByDesc('created_at')->paginate(30)->through(function($b){$data=$b->toArray();if($data['payment_attention'])$data['payment_attention']='El establecimiento está revisando un detalle de tu reservación. Contacta al negocio para recibir ayuda.';return $data;});}
 public function cancel(Request $r,Booking $booking){abort_unless($booking->user_id===$r->user()->id,403);DB::transaction(function()use($booking){Venue::whereKey($booking->venue_id)->lockForUpdate()->firstOrFail();$b=Booking::whereKey($booking->id)->lockForUpdate()->firstOrFail();abort_if($b->checkoutAttempts()->whereIn('status',['creating','pending','unknown'])->where('expires_at','>',now())->exists(),422,'Hay un pago o ficha vigente. Espera su vencimiento o contacta al establecimiento antes de cancelar.');abort_if($b->paid_total>0,422,'Esta reserva tiene pagos registrados. Contacta al establecimiento para revisar la cancelación.');abort_unless($b->status==='hold',422,'Solo puedes cancelar apartados pendientes desde esta pantalla.');$b->update(['status'=>'cancelled']);});return ['ok'=>true];}
}
